WITH cleaned AS (SELECT *, temp_c * status_bits AS temp_c_times_status_bits, temp_c * humidity AS temp_c_times_humidity FROM device_readings WHERE temp_c IS NULL) SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, temp_c_times_status_bits, temp_c_times_humidity, RANK() OVER (PARTITION BY device_code ORDER BY status_bits) AS status_bits_rank, SUM(temp_c_times_status_bits) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS temp_c_times_status_bits_sum_15m, SUM(temp_c_times_humidity) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS temp_c_times_humidity_sum_1h FROM cleaned
